using System.Diagnostics;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Runtime;
using System.Text.Json;
using Nitrogen;

var source = File.ReadAllText(args[0]);
var warmups = int.Parse(args[1]);
var runs = int.Parse(args[2]);
var incremental = args[3] == "incremental";
var setup = Stopwatch.StartNew();
var assembly = Assembly.GetExecutingAssembly();
var modules = assembly.GetTypes()
    .Where(t => t.Namespace == "Nitride.NitrogenBench.CSharp4" && typeof(SyntaxModule).IsAssignableFrom(t) && !t.IsAbstract)
    .Select(t => t.GetProperty("Instance", BindingFlags.Public | BindingFlags.Static)?.GetValue(null)
        ?? t.GetField("Instance", BindingFlags.Public | BindingFlags.Static)?.GetValue(null))
    .OfType<SyntaxModule>().ToArray();
if (modules.Length != 30) throw new Exception($"Expected30 modules, got{modules.Length}");
var builder = new LanguageBuilder();
foreach (var module in modules) builder.Add(module);
var language = builder.Build();
var type = assembly.GetType("Nitride.NitrogenBench.CSharp4.CompilationUnitsModule")!;
var member = type.GetMember("CompilationUnit").Single();
var start = (Rule)(member is FieldInfo field ? field.GetValue(null)! : ((PropertyInfo)member).GetValue(null)!);
setup.Stop();
ParseResult Parse() => incremental ? language.ParseIncremental(source, start) : language.Parse(source, start);
void Validate(ParseResult result) {
    if (!result.Success || result.HasErrors || result.Tree.Text.Length != source.Length)
        throw new Exception("Benchmark input rejected or errored");
}
for (int i=0; i<warmups; i++) { using var warm = Parse(); Validate(warm); }
var samples = new List<object>();
for (int i=0; i<runs; i++) {
    var clock = Stopwatch.StartNew();
    var result = Parse();
    clock.Stop();
    var elapsed = (long)clock.Elapsed.TotalNanoseconds;
    Validate(result);
    var span = result.Tree.Span(result.Tree.Root);
    samples.Add(new {elapsed_ns=elapsed, errors=result.Diagnostics.Length, source_length=result.Tree.Text.Length,
        nodes=result.Tree.NodeCount, root_span=new[]{span.Start,span.End}, incremental=result.IsIncremental,
        stats=result.Stats});
    GC.KeepAlive(result.Tree);
    result.Dispose();
}
var runtimeAssembly = typeof(Language).Assembly;
Console.WriteLine(JsonSerializer.Serialize(new {
    nitrogen_version=runtimeAssembly.GetName().Version!.ToString(),
    nitrogen_build=runtimeAssembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion,
    runtime=RuntimeInformation.FrameworkDescription, architecture=RuntimeInformation.ProcessArchitecture.ToString(),
    server_gc=GCSettings.IsServerGC, tiered_pgo=Environment.GetEnvironmentVariable("DOTNET_TieredPGO"),
    warmups, runs, mode=incremental?"incremental-initial":"one-shot", modules=modules.Length,
    language_setup_ns=(long)setup.Elapsed.TotalNanoseconds, samples
}));

